3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Create-time normalisation for {@code POST /owners}: canonicalises the telephone to E.164 form
8	 * (see {@link OwnerTelephone#toE164(String)}). The canonical value is written back onto the body
9	 * in place (the {@code @Val} object is the same instance {@link BuildOwner} then maps), so it is
10	 * what gets stored and returned. A value that cannot form a valid E.164 number is rejected with
11	 * 400 via {@link InvalidTelephoneException}.
12	 *
13	 * <p>Runs after {@link ValidateOwnerFields} (which has already guaranteed telephone is present
14	 * and non-blank) and before {@link BuildOwner}.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        String original = request.getTelephone();
20	        String e164 = OwnerTelephone.toE164(original);
21	        if (e164 == null) {
22	            throw new InvalidTelephoneException(original);
23	        }
24	        request.setTelephone(e164);
25	    }
26	}
