1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Create-time email handling for {@code POST /owners}. Email is optional: an absent (null or
8	 * blank) value is left untouched and the request proceeds. When a value is supplied it must be
9	 * a syntactically valid address — otherwise the request is rejected with 400 via
10	 * {@link InvalidEmailException}. A valid value is normalised (trimmed and lower-cased) and
11	 * written back onto the body in place (the {@code @Val} object is the same instance
12	 * {@link BuildOwner} then maps), so the lower-cased form is what gets stored and returned.
13	 *
14	 * <p>Runs after {@link NormalizeOwnerTelephone} and before {@link CheckOwnerTelephoneUnique}.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
19	        String email = request.getEmail();
20	        if (!OwnerEmail.isPresent(email)) {
21	            return;
22	        }
23	        if (!OwnerEmail.isValid(email)) {
24	            throw new InvalidEmailException(email);
25	        }
26	        request.setEmail(OwnerEmail.normalize(email));
27	    }
28	}
