1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where
9	 * {@code LAST3} is the upper-cased first three letters of {@code lastName} and
10	 * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the
11	 * current number of owners (e.g. {@code SMI-0007}).
12	 *
13	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, so the count reflects
14	 * the owners that already exist and excludes the owner being created.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String lastName = owner.getLastName();
20	        int length = Math.min(3, lastName.length());
21	        String prefix = lastName.substring(0, length).toUpperCase();
22	        int sequence = ownerRepository.findAll().size() + 1;
23	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
24	    }
25	}
