1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Single source of truth for the owner email rule used by the {@code POST /owners} pipeline:
8	 * email is optional, but when supplied it must be a syntactically valid address and is stored
9	 * and returned lower-cased. Centralised here (rather than inlined in {@link NormalizeOwnerEmail})
10	 * so the notions of "present", "valid" and "normalised" stay defined in one place.
11	 */
12	final class OwnerEmail {
13	
14	    /**
15	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a domain with
16	     * at least one dot and non-empty labels, none containing whitespace or {@code @}.
17	     */
18	    private static final Pattern VALID = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
19	
20	    private OwnerEmail() {
21	    }
22	
23	    /** An email is "present" when it is non-null and not blank. */
24	    static boolean isPresent(String email) {
25	        return email != null && !email.isBlank();
26	    }
27	
28	    /** Whether the (present) value is a syntactically valid address. */
29	    static boolean isValid(String email) {
30	        return email != null && VALID.matcher(email.trim()).matches();
31	    }
32	
33	    /** The stored/returned form: trimmed and lower-cased. */
34	    static String normalize(String email) {
35	        return email.trim().toLowerCase(Locale.ROOT);
36	    }
37	}
