31	    @Mapping(target = "pets", ignore = true)
32	    Owner toOwner(OwnerFieldsDto ownerDto);
33	
34	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
35	
36	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
37	
38	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
39	        OwnerPageDto ownerPageDto = new OwnerPageDto();
40	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
41	        ownerPageDto.setPage(ownerPage.getNumber());
42	        ownerPageDto.setSize(ownerPage.getSize());
43	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
44	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
