4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** household-duplicate: Reject creating an owner when another owner has the same lastName and the same address (co... */
8	class AcceptanceTest extends AcceptanceBase {
9	
